# Generated by Descant: acceptance tests.
# frozen_string_literal: true

require "rails_helper"
require "rake"

RSpec.describe "timekeeping:alerts" do
  it "still prints the monolith-side pending intent alert and then exits non-zero when the metrics read fails" do
    Rails.application.load_tasks unless Rake::Task.task_defined?("timekeeping:alerts")
    company = create(:company)
    quiet_company = create(:company)
    InvoiceOperationIntent.create!(company_id: company.id, invoice_id: 1, operation_id: SecureRandom.uuid,
                                   generation: 1, state: "pending", created_at: 11.minutes.ago)
    InvoiceOperationIntent.create!(company_id: quiet_company.id, invoice_id: 2, operation_id: SecureRandom.uuid,
                                   generation: 1, state: "pending", created_at: 9.minutes.ago)

    base_url = "http://timekeeping.test"
    stub_request(:get, "#{base_url}/internal/v1/metrics").to_return(status: 500, body: "boom")
    allow(ENV).to receive(:[]).and_call_original
    allow(ENV).to receive(:[]).with("TIMEKEEPING_BASE_URL").and_return(base_url)
    allow(ENV).to receive(:[]).with("TIMEKEEPING_SERVICE_TOKEN").and_return("service-#{SecureRandom.hex(24)}")

    # "invoice operation intents still `pending` older than 10 minutes" is read from the
    # monolith's own records, so a Timekeeping outage must not swallow it; the failed
    # read itself must still fail the command rather than pass as "no alerts".
    exit_error = nil
    output = capture_stdout_for_alerts_task do
      Rake::Task["timekeeping:alerts"].reenable
      Rake::Task["timekeeping:alerts"].invoke
    rescue SystemExit => e
      exit_error = e
    end

    expect(exit_error).not_to be_nil
    expect(exit_error.success?).to be(false)
    expect(output).to include("company_id=#{company.id}")
    expect(output).not_to include("company_id=#{quiet_company.id}")
  end

  def capture_stdout_for_alerts_task
    original = $stdout
    $stdout = StringIO.new
    yield
    $stdout.string
  ensure
    $stdout = original
  end
end
